1	import { vi } from "vitest";
2	import { runInNewContext } from "node:vm";
3	import { H3, HTTPError, type H3Event } from "../src/index.ts";
4	import { describeMatrix } from "./_setup.ts";
5	
6	describeMatrix("errors", (t, { it, expect, describe }) => {
7	  const consoleMock = ((globalThis.console.error as any) = vi.fn());
8	
9	  describe("error response bodies", () => {
10	    for (const withOnError of [false, true]) {
11	      const hook = withOnError ? "with onError" : "without onError";
12	
13	      it(`omits the body for a missing HEAD route ${hook}`, async () => {
14	        if (!withOnError) t.app.config.onError = undefined;
15	        const res = await t.fetch("/missing", { method: "HEAD" });
16	        expect(res.status).toBe(404);
17	        // A HEAD body is not rendered, so no (mismatching) content-length is advertised
18	        expect(res.headers.get("content-length")).toBeNull();
19	        expect(await res.text()).toBe("");
20	        expect(t.hooks.onError).toHaveBeenCalledTimes(withOnError ? 1 : 0);
21	        expect(t.hooks.onResponse).toHaveBeenCalledTimes(1);
22	      });
23	
24	      for (const asyncHandler of [false, true]) {
25	        for (const method of ["GET", "HEAD"]) {
26	          it(`renders ${method} errors from a ${asyncHandler ? "async" : "sync"} handler ${hook}`, async () => {
27	            if (!withOnError) t.app.config.onError = undefined;
28	            const handler = (event: H3Event) => {
29	              event.res.headers.set("x-success", "success");
30	              event.res.errHeaders.set("x-error", "prepared");
31	              event.res.errHeaders.append("set-cookie", "prepared=1");
32	              throw new HTTPError({
33	                status: 422,
